# Log-linear attention (Guo et al. 2025): linear attention with a hierarchical (Fenwick-tree) level mask; each level has
# its own data-dependent weight, combined with Mamba-2 style segsum decay.
# Source: fla-org/flash-linear-attention fla/ops/log_linear_attn/naive.py (naive_log_linear_attn), MIT.
import math
import torch
import torch.nn as nn


def segsum(x):
    T = x.size(-1)
    x_cumsum = torch.cumsum(x, dim=-1)
    x_segsum = x_cumsum[..., :, None] - x_cumsum[..., None, :]
    mask = torch.tril(torch.ones(T, T, device=x.device, dtype=bool))
    return x_segsum.masked_fill(~mask, -torch.inf)


def construct_level_mask(level, L):
    T = L.size(-1)
    if level == 0:
        return torch.diag_embed(L[..., level, :])
    indices = torch.cartesian_prod(torch.arange(T), torch.arange(T)).to(L.device)
    mask = torch.where(
        torch.logical_and(
            torch.logical_and(
                indices[:, 0] % (1 << level) >= (1 << (level - 1)),
                indices[:, 1] + (1 << (level - 1)) >= indices[:, 0] - (indices[:, 0] % (1 << (level - 1))),
            ),
            indices[:, 1] < indices[:, 0] - (indices[:, 0] % (1 << (level - 1))),
        ).view(T, T),
        L[..., level, :].unsqueeze(-1).expand(*([-1] * (len(L.shape) - 2)), T, T),
        0,
    )
    return mask


def construct_H_matrix(a, L):
    T = a.size(-1)
    A = torch.exp(segsum(a))
    H = torch.zeros_like(A)
    for level in range(int(math.ceil(math.log2(T))) + 1):
        H += A * construct_level_mask(level, L)
    return H


def naive_log_linear_attn(q, k, v, g, level_scales, scale=1.0):
    if scale is None:
        scale = q.shape[-1] ** -0.5
    num_groups, num_heads = k.shape[2], v.shape[2]
    if num_groups != num_heads:
        q = q.repeat_interleave(num_heads // num_groups, dim=2)
        k = k.repeat_interleave(num_heads // num_groups, dim=2)
    H = construct_H_matrix(g.permute(0, 2, 1), level_scales.permute(0, 2, 3, 1))
    M = torch.einsum("bhlc,blhn,bchn->bhlc", H, q, k)
    return torch.einsum("bhlc,bchp->blhp", M, v) * scale


class Model(nn.Module):
    def forward(self, q, k, v, g, level_scales):
        return naive_log_linear_attn(q, k, v, g, level_scales, scale=q.shape[-1] ** -0.5)


B, T, H, DK, DV = 2, 128, 4, 64, 64
NUM_LEVELS = int(math.ceil(math.log2(T))) + 1


def get_inputs():
    q = torch.randn(B, T, H, DK)
    k = torch.randn(B, T, H, DK)
    v = torch.randn(B, T, H, DV)
    g = torch.nn.functional.logsigmoid(torch.randn(B, T, H) + 3.0)  # per-head log decay
    level_scales = torch.rand(B, T, H, NUM_LEVELS)                  # per-level weights lambda
    return [q, k, v, g, level_scales]


