# BitNet b1.58 BitLinear (training-time fake-quant form): ternary absmean weight quantization
# (round(W / mean|W|) clamped to {-1,0,1}) and per-token absmax int8 activation quantization, then linear.
# Source: huggingface/transformers src/transformers/integrations/bitnet.py (WeightQuant, ActQuant, AutoBitLinear
# forward), Apache-2.0. Autograd STE wrappers dropped (forward only).
import torch
import torch.nn as nn
import torch.nn.functional as F


def weight_quant(weight):
    dtype = weight.dtype
    weight = weight.float()
    scale = 1.0 / weight.abs().mean().clamp_(min=1e-5)
    return ((weight * scale).round().clamp(-1, 1) / scale).to(dtype)


def act_quant(activation):
    dtype = activation.dtype
    activation = activation.float()
    scale = 127 / activation.abs().max(dim=-1, keepdim=True).values.clamp_(min=1e-5)
    return ((activation * scale).round().clamp(-128, 127) / scale).to(dtype)


class Model(nn.Module):
    def __init__(self, in_features=4096, out_features=11008):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features) * in_features ** -0.5)

    def forward(self, x):
        return F.linear(act_quant(x), weight_quant(self.weight))


